import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
const at=p=>pathToFileURL(resolve(p)).href;
const {createFirstRunController}=await import(at('app/ui/src/screens/first-run/controller.ts'));
const {pinOf}=await import(at('app/ui/src/screens/first-run/review.ts'));
const {actualEngineJoin,engineJoinDigest}=await import(at('app/ui/tests/first-run/engine-join.fixture.ts'));
const digest=async()=>createHash('sha256').update(await readFile('app/ui/src/screens/first-run/controller.ts')).digest('hex');
const before=await digest(),cases=[];
for(const operation of ['settings','publish']) for(const departure of ['cancel','invalidate']){
 const cleanup=[];
 try {
  const f=await actualEngineJoin({after:callback=>cleanup.push(callback)});
  let controller,armed=false,triggered=false;
  const guard={live(){
   if(armed&&!triggered){triggered=true;if(departure==='cancel')controller.cancel();else controller.invalidate('VAULT_LOCKED');}
   return true;
  }};
  controller=createFirstRunController(f.port,{guard,digest:engineJoinDigest,createAttemptId:()=> 'independent-reentry-'+operation+'-'+departure});
  await controller.load();controller.choosePack('retail');
  for(let i=0;i<64;i++)await Promise.resolve();
  const review=controller.snapshot().review,pin=pinOf(review);
  for(const row of review.rows)controller.acceptRow(row.definition.name,pin);
  controller.acceptSettings(pin);armed=true;
  let result,leaked=false;
  if(operation==='settings'){
   const response=controller.leaveToSettings(review.revision);
   if(response.ok)leaked=response.admit()!==null;
   result=response.ok?{ok:true,admitted:leaked}:response;
  }else result=await controller.publishDictionary(pin);
  cases.push({operation,departure,triggered,result,state:controller.snapshot().kind,
   publishDispatches:f.count('ontology.publish'),settingsAdmitted:leaked,
   status:triggered && !leaked && f.count('ontology.publish')===0 && result.ok===false ? 'passed':'failed'});
 }catch(error){cases.push({operation,departure,status:'error',error:String(error)});}
 finally{for(const done of cleanup.reverse())await done();}
}
const after=await digest();console.log(JSON.stringify({kind:'independent-entry-guard-reentry',before,after,sourceStable:before===after,cases},null,2));
