const hash=b=>createHash('sha256').update(b).digest('hex');
const entries=JSON.parse(readFileSync('verification/backend-join-code-eol-equivalence.json','utf8'));
const normalize=b=>Buffer.from([...b].filter((byte,index)=>!(byte===13&&b[index+1]===10)));
