 const rawPath=entry.changedWorkingBytes?'verification/join-before-canonical-'+basename(entry.path)+'.raw':resolve(checkout,entry.path);
 const raw=readFileSync(rawPath),current=readFileSync(resolve(checkout,entry.path));
 const staged=spawnSync('git',['-c','safe.directory='+checkout.replaceAll('\\','/'),'show',':'+entry.path],{cwd:checkout,maxBuffer:1024*1024*4});
 assert.equal(staged.status,0);
 assert.equal(hash(raw),entry.rawSha256);assert.equal(hash(current),entry.canonicalSha256);
 assert.equal(raw.length,entry.rawBytes);assert.equal(current.length,entry.canonicalBytes);
 assert.ok(normalize(raw).equals(current),'Exact CRLF replacement failed: '+entry.path);
 assert.ok(staged.stdout.equals(current),'Staged Git bytes differ: '+entry.path);
 return {path:entry.path,rawPath,rawSha256:hash(raw),canonicalSha256:hash(current),
 rawBytes:raw.length,canonicalBytes:current.length,exactCrLfToLf:true,workingEqualsStagedGitBytes:true};
});
