for(const[file,expected]of Object.entries({
 'verification/backend-join-independent-review-before-canonical.md':'31759a65a32bb7f37cb22e6f45c40d4e5675a75a80e39f36eb8930a3ae3d3780',
 'verification/backend-join-independent-review-before-canonical.json':'9844087302b64902160cc75e69964038db419c2d0e7651c136565355caed72ee'
})){archived[file]=hash(readFileSync(file));assert.equal(archived[file],expected);}
console.log(JSON.stringify({checks,changedFiles:entries.filter(e=>e.changedWorkingBytes).length,unchangedFiles:entries.filter(e=>!e.changedWorkingBytes).length,archiveHashes:archived,status:'passed'},null,2));
